"""Original environmental emergencies: altitude and diving illness."""
from create_critical_drowning_electrical import rows,q,HE,FR,RC,AH,LI,BU,ref
AL=ref('Wilderness Medical Society acute altitude illness guideline: 2024','https://doi.org/10.1016/j.wem.2023.05.013')
DI=ref('CDC Yellow Book: scuba diving and decompression illness','https://www.cdc.gov/yellow-book/hcp/environmental-hazards-risks/scuba-diving-decompression-illness-and-other-dive-related-injuries.html')
DA=ref('Divers Alert Network: decompression illness and treatment','https://dan.org/health-medicine/health-resources/diseases-conditions/decompression-illness-what-is-it-and-what-is-the-treatment/')

q('A traveler rapidly ascends to 3,500 m and develops headache, nausea and fatigue without ataxia or dyspnea at rest. Which diagnosis is most likely?', 'Acute mountain sickness',[
 ('High-altitude cerebral edema already established','Ataxia or altered mental status would support HACE.'),('High-altitude pulmonary edema already established','The stem lacks the characteristic resting respiratory findings.'),('Decompression sickness','This is not a compressed-gas diving exposure.')],
 'Recognize early altitude illness before severe progression','**AMS commonly follows ascent before acclimatization is adequate.**',['Symptoms are nonspecific, so assess dehydration, infection and other causes.','Neurological deterioration or resting dyspnea changes urgency.'],'**Stop ascent and treat symptoms; descend if worsening or not improving.**',['Acetazolamide can facilitate acclimatization in appropriate cases.','Do not ascend further while symptomatic.'],[['AMS','Headache plus compatible symptoms after ascent'],['HACE','Ataxia/mental-status change'],['HAPE','Respiratory syndrome']],[AL],style='clinical_scenario')

q('At high altitude, a patient with recent headache becomes ataxic and confused. What is the immediate management principle?', 'Urgent descent with oxygen and dexamethasone as indicated',[
 ('Continue ascent to accelerate acclimatization','Further ascent worsens hypoxic stress.'),('Treat only with analgesia and observe overnight at the same altitude','This is unsafe for suspected HACE.'),('Use acetazolamide as a substitute for descent in severe neurological illness','It does not replace emergency evacuation and oxygenation.')],
 'HACE is a life-threatening neurological emergency','**Ataxia and altered mental status after ascent require urgent action.**',['Protect the airway and assist evacuation; do not let an ataxic patient descend alone.','A portable hyperbaric chamber can be a temporary measure when descent is delayed.'],'**Treat while organizing definitive reduction in altitude.**',['Look for associated HAPE.','Do not delay because an exact altitude or imaging threshold has not been reached.'],[['Diagnosis','Suspected HACE'],['Definitive action','Descent'],['Adjuncts','Oxygen/dexamethasone and selected chamber use']],[AL],style='clinical_scenario')

q('A climber has dyspnea at rest, cough, marked hypoxemia and crackles after ascent, without known heart disease. What best describes the usual HAPE mechanism?', 'Uneven hypoxic pulmonary vasoconstriction causing high microvascular pressure and capillary stress',[
 ('Primary left-ventricular failure as the defining mechanism','HAPE is usually a noncardiogenic edema syndrome.'),('Generalized fluid overload as a required cause','It can occur without excess total-body volume.'),('Bacterial pneumonia as the only possible explanation','Infection is a differential, but the altitude pattern supports HAPE.')],
 'Noncardiogenic does not mean pressure-independent','**Excessive pulmonary vascular responses can produce edema without left-heart failure.**',['Exercise and continued ascent can worsen the condition.','AMS need not precede HAPE.'],'**Give oxygen and descend with minimal exertion.**',['Selected vasodilator treatment is an adjunct when definitive measures are limited.','Routine diuresis is not the standard solution for an often volume-depleted climber.'],[['Pressure source','Pulmonary vascular response'],['Left heart','Usually not the primary failure'],['Treatment','Oxygen and descent']],[AL],style='clinical_scenario')

q('How does acetazolamide help prevent acute mountain sickness?', 'Carbonic anhydrase inhibition promotes bicarbonate loss and stimulates ventilation, facilitating acclimatization',[
 ('It directly increases inspired oxygen concentration','It changes physiology rather than the ambient oxygen fraction.'),('It produces respiratory depression to reduce oxygen demand','Its useful effect includes increased ventilation.'),('It neutralizes pulmonary edema fluid directly','It is not a substitute for HAPE treatment.')],
 'Accelerate adaptation rather than mask every symptom','**A mild metabolic acidifying effect offsets altitude-related respiratory alkalosis.**',['The drug can improve acclimatization and periodic breathing.','Dose and contraindication assessment follow the risk-based protocol.'],'**Combine medication with an appropriate ascent schedule.**',['Medication does not make rapid ascent risk-free.','Dexamethasone does not produce the same acclimatization mechanism.'],[['Mechanism','Carbonic anhydrase inhibition'],['Effect','Bicarbonate loss/ventilatory stimulation'],['Foundation','Gradual ascent']],[AL])

q('Which measure most reliably reduces acute altitude-illness risk for a traveler with time to plan?', 'Gradual ascent with appropriate increases in sleeping altitude and acclimatization days',[
 ('Excellent aerobic fitness alone','Fitness does not reliably prevent AMS.'),('A high fluid intake sufficient to produce weight gain','Overhydration does not prevent altitude illness and can be harmful.'),('Prophylactic diuresis in every traveler','Volume depletion is not a safe prevention strategy.')],
 'Exposure rate is a controllable determinant','**Acclimatization requires time.**',['Prior illness, ascent profile and sleeping altitude inform risk.','Fitness and previous successful travel do not guarantee protection.'],'**Use risk-based prophylaxis when appropriate and a clear descent plan.**',['Recognize symptoms early and stop ascent.','Avoid excess sedatives and alcohol that can impair breathing or judgment.'],[['Main prevention','Gradual ascent'],['Fitness','Not reliable protection'],['Contingency','Recognize illness and descend']],[AL])

q('A patient with suspected HAPE improves rapidly on oxygen while evacuation is arranged. Which statement is correct?', 'Improvement does not justify renewed ascent or unnecessary exertion',[
 ('Oxygen response proves the original diagnosis was anxiety','Hypoxic pulmonary disease can improve with oxygen.'),('A normal saturation on oxygen means no further monitoring is needed','The patient remains dependent on treatment and the course can change.'),('Strenuous walking upward is the best next treatment','Exertion and further ascent can worsen pulmonary vascular stress.')],
 'Response to support is not proof of safe re-exposure','**Oxygen reduces hypoxic stress while descent addresses the environment.**',['Continue reassessment of breathing, perfusion and neurological state.','The safest evacuation minimizes exertion when feasible.'],'**Complete the treatment and evacuation plan.**',['Assess for alternative or concurrent diagnoses if response is poor.','Plan future ascent only after recovery and appropriate medical advice.'],[['Oxygen response','Helpful but not full recovery'],['Activity','Minimize exertion'],['Further ascent','Unsafe during active illness']],[AL],style='clinical_scenario')

q('A diver develops sudden focal neurological deficits immediately after a rapid ascent while holding breath. Which mechanism is most likely?', 'Pulmonary barotrauma with arterial gas embolism',[
 ('Nitrogen narcosis persisting solely from ambient pressure at depth','Narcosis occurs during pressure exposure and usually improves with ascent.'),('Simple external-ear barotrauma','This does not explain abrupt focal cerebral deficits.'),('Acute mountain sickness','The exposure and immediate neurological syndrome are different.')],
 'Expanding gas can enter the arterial circulation','**Breath holding during ascent can overexpand the lungs.**',['Gas entry into pulmonary veins can embolize the brain or other organs.','Serious injury can follow a relatively shallow ascent.'],'**Give high-concentration oxygen and arrange urgent dive-medicine/recompression assessment.**',['Assess for pneumothorax and other barotrauma.','Do not delay consultation for a reassuring initial scan.'],[['Trigger','Rapid ascent/breath holding'],['Pathway','Pulmonary overexpansion to arterial gas'],['Treatment','Oxygen and urgent recompression evaluation']],[DI],style='clinical_scenario')

q('Several hours after repeated dives, a diver develops joint pain, paresthesia and leg weakness. Which diagnosis is most likely?', 'Decompression sickness',[
 ('Nitrogen narcosis as the usual delayed surface syndrome','Narcosis is linked to increased gas partial pressure at depth.'),('Simple muscle strain as established despite neurological deficits','Neurological findings after diving require urgent DCI assessment.'),('Isolated middle-ear squeeze','This does not explain the systemic and spinal-type findings.')],
 'Inert-gas bubbles can injure tissues during decompression','**DCS can affect joints, skin, spinal cord, brain and other systems.**',['The dive profile and timing support assessment but do not replace examination.','A seemingly compliant profile does not eliminate the possibility.'],'**Provide oxygen and seek urgent specialist recompression advice.**',['Perform and document serial neurological examinations.','Avoid flying or further altitude exposure.'],[['Pain','May involve joints'],['Neurology','Potential spinal/CNS injury'],['Action','Treat suspected DCI urgently']],[DI,DA],style='clinical_scenario')

q('What is the appropriate first-aid treatment for suspected decompression illness while arranging specialist care?', 'High-concentration oxygen with supportive care and urgent recompression consultation',[
 ('Return underwater for improvised air recompression','This creates major drowning and worsening-exposure risks without a controlled specialist protocol.'),('Wait for symptoms to recur before contacting anyone','Transient improvement does not exclude important injury.'),('Fly immediately in an unpressurized aircraft to save time without discussing altitude risk','Reduced pressure can worsen bubble-related injury.')],
 'Initial improvement does not erase decompression injury','**Oxygen supports tissue oxygenation and inert-gas elimination.**',['Definitive care may require recompression.','Transport decisions should minimize further pressure reduction where feasible.'],'**Contact dive-medicine expertise promptly.**',['Assess airway, breathing, circulation and neurological findings.','Treat dehydration appropriately without forcing oral intake in an impaired patient.'],[['First aid','High-concentration oxygen'],['Definitive assessment','Recompression specialist'],['Avoid','Further uncontrolled decompression']],[DA])

q('Why can a normal initial CT brain not exclude neurological decompression illness?', 'The diagnosis is primarily clinical and bubble-related or spinal injury may not be visible on routine CT',[
 ('CT directly measures dissolved nitrogen in every tissue','Routine CT does not provide this assessment.'),('Only a large visible arterial bubble can cause symptoms','Microvascular injury and other mechanisms can produce neurological deficits.'),('Normal imaging means recompression can always be safely cancelled','Specialist treatment decisions depend on the exposure and clinical syndrome.')],
 'Imaging can exclude alternatives without excluding DCI','**Neurological decompression illness is not defined by a required CT lesion.**',['Evaluate stroke, trauma and other emergencies as appropriate.','Do not let non-diagnostic imaging create a harmful delay.'],'**Obtain urgent dive-medicine advice and serial examination.**',['Document onset and evolution relative to the dive.','Continue oxygen while the definitive plan is made.'],[['CT','May be normal'],['Diagnosis','Exposure plus clinical findings'],['Priority','Timely specialist treatment']],[DI,DA])

q('At depth, a diver becomes euphoric, inattentive and poorly coordinated, then improves with controlled ascent. Which diagnosis best fits?', 'Nitrogen narcosis',[
 ('Decompression sickness as the typical depth-dependent reversible syndrome','DCS usually develops during or after decompression, not simply from high inert-gas pressure at depth.'),('CNS oxygen toxicity established by euphoria alone','Oxygen toxicity has a different exposure relationship and can include seizures.'),('Arterial gas embolism from lung overexpansion before ascent','AGE classically follows decompression-related pulmonary injury.')],
 'Gas partial pressure changes neurological function','**Inert-gas narcosis worsens with depth and can impair judgment.**',['Task loading, CO2 retention and individual variability affect performance.','Impaired judgment can turn a reversible syndrome into a fatal accident.'],'**Ascend in a controlled manner with appropriate diving support.**',['Avoid rapid panic ascent and breath holding.','Use training, suitable gas and dive planning to reduce risk.'],[['At depth','Narcosis risk'],['Controlled ascent','Usually improves'],['Hazard','Impaired judgment/coordination']],[DI],style='clinical_scenario')

q('A diver using an oxygen-rich gas mixture at excessive oxygen partial pressure develops a seizure underwater. Which mechanism is a concern?', 'Central nervous system oxygen toxicity',[
 ('A guarantee of hypoglycemia based on seizure alone','Glucose should be assessed, but the gas exposure is a specific clue.'),('Pure decompression sickness caused only by the elevated oxygen fraction','DCS relates to inert-gas decompression; the oxygen exposure creates a separate toxicity risk.'),('A benign event that permits continuing the same dive','Underwater seizure creates an immediate drowning hazard.')],
 'More oxygen is not always safe at increased pressure','**CNS toxicity depends on oxygen partial pressure and exposure conditions.**',['CO2 retention and exertion can increase risk.','The rescue must avoid drowning and uncontrolled ascent.'],'**Use trained diving rescue and medical assessment.**',['Review the gas mixture, depth and exposure duration.','Do not resume diving without an appropriate evaluation.'],[['Exposure','High oxygen partial pressure'],['Manifestation','Seizure risk'],['Immediate danger','Loss of airway underwater']],[DI],style='clinical_scenario')
